mapper.sql:
FROM AP_BOARD b
WHERE b.USE_YN = 'Y'

	AND b.TYPE = #{boardType}


	AND SUBSTRING(b.POST_DT, 1, 4) = #{year}


	AND (
		b.TITLE LIKE CONCAT('%', #{keyword}, '%')
		OR b.CONTENT LIKE CONCAT('%', #{keyword}, '%')
	)

mapper.update:
/* BoardDao.updateBoardViewCount */
UPDATE AP_BOARD
SET VIEW_CNT = VIEW_CNT + 1
WHERE BOARD_NO = #{boardNo}
AND USE_YN = 'Y'

/* BoardDao.deleteBoard */
UPDATE AP_BOARD
SET USE_YN = 'N',
	UPDT_DDTM = DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'),
	UPDTR_EMPNO = #{userNo},
	UPDTR_IP = #{clientIp}
WHERE BOARD_NO = #{boardNo}
AND USE_YN = 'Y'
